Index: cmd/entire/cli/agent/opencode/entire_plugin.ts
===================================================================
--- cmd/entire/cli/agent/opencode/entire_plugin.ts	
+++ cmd/entire/cli/agent/opencode/entire_plugin.ts	
@@ -1,187 +1,205 @@
 // Entire CLI plugin for OpenCode
 // Auto-generated by `entire enable --agent opencode`
 // Do not edit manually — changes will be overwritten on next install.
 // Requires Bun runtime (used by OpenCode's plugin system for loading ESM plugins).
 import type { Plugin } from "@opencode-ai/plugin"

 export const EntirePlugin: Plugin = async ({ directory }) => {
   const ENTIRE_CMD = '__ENTIRE_CMD__'
   // Track seen user messages to fire turn-start only once per message
   const seenUserMessages = new Set<string>()
   // Track current session ID for message events (which don't include sessionID)
   let currentSessionID: string | null = null
   // Track the model used by the most recent assistant message
   let currentModel: string | null = null
   // In-memory store for message metadata (role, tokens, etc.)
   const messageStore = new Map<string, any>()
+  // Track sessions with a started turn that still needs a turn-end hook.
+  const sessionsWithOpenTurn = new Set<string>()

+  function maybeStartTurn(sessionID: string | null, messageID: string, prompt: string) {
+    if (!sessionID || seenUserMessages.has(messageID)) {
+      return
+    }
+    seenUserMessages.add(messageID)
+    sessionsWithOpenTurn.add(sessionID)
+    return callHook("turn-start", {
+      session_id: sessionID,
+      prompt,
+      model: currentModel ?? "",
+    })
+  }
+
   /**
    * Build the shell command for a hook invocation.
    * Uses sh -c so that shell command substitution in ENTIRE_CMD
    * (e.g., $(git rev-parse --show-toplevel) for local-dev) is interpreted.
    */
   function hookCmd(hookName: string): string[] {
     if (ENTIRE_CMD !== "entire") {
       return ["sh", "-c", `${ENTIRE_CMD} hooks opencode ${hookName}`]
     }
     return ["sh", "-c", `if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks opencode ${hookName}`]
   }

   /**
    * Pipe JSON payload to an entire hooks command (async).
    * Errors are logged but never thrown — plugin failures must not crash OpenCode.
    */
   async function callHook(hookName: string, payload: Record<string, unknown>) {
     try {
       const json = JSON.stringify(payload)
       const proc = Bun.spawn(hookCmd(hookName), {
         cwd: directory,
         stdin: new Blob([json + "\n"]),
         stdout: "ignore",
         stderr: "ignore",
       })
       await proc.exited
     } catch {
       // Silently ignore — plugin failures must not crash OpenCode
     }
   }

   /**
    * Synchronous variant for hooks that fire near process exit (turn-end, session-end).
    * `opencode run` breaks its event loop on the same session.status idle event that
    * triggers turn-end. The async callHook would be killed before completing.
    * Bun.spawnSync blocks the event loop, preventing exit until the hook finishes.
    */
   function callHookSync(hookName: string, payload: Record<string, unknown>) {
     try {
       const json = JSON.stringify(payload)
       Bun.spawnSync(hookCmd(hookName), {
         cwd: directory,
         stdin: new TextEncoder().encode(json + "\n"),
         stdout: "ignore",
         stderr: "ignore",
       })
     } catch {
       // Silently ignore — plugin failures must not crash OpenCode
     }
   }

   return {
     event: async ({ event }) => {
       try {
         switch (event.type) {
           case "session.created": {
             const session = (event as any).properties?.info
             if (!session?.id) break
             // Reset per-session tracking state when switching sessions.
             if (currentSessionID !== session.id) {
               seenUserMessages.clear()
               messageStore.clear()
+              sessionsWithOpenTurn.clear()
               currentModel = null
               const json = JSON.stringify({
                 session_id: session.id,
               })
               const proc = Bun.spawn(hookCmd("session-start"), {
                 cwd: directory,
                 stdin: new Blob([json + "\n"]),
                 stdout: "ignore",
                 stderr: "ignore",
               })
               await proc.exited
             }
             currentSessionID = session.id
             break
           }

           case "message.updated": {
             const msg = (event as any).properties?.info
             if (!msg) break
             // Store message metadata (role, time, tokens, etc.)
             messageStore.set(msg.id, msg)
+            if (msg.role === "user") {
+              // Fallback for run-mode where message.part.updated can be absent/late.
+              const prompt = typeof msg.content === "string" ? msg.content : ""
+              await maybeStartTurn(msg.sessionID ?? currentSessionID, msg.id, prompt)
+            }
             // Track model from assistant messages
             if (msg.role === "assistant" && msg.modelID) {
               currentModel = msg.modelID
             }
             break
           }

           case "message.part.updated": {
             const part = (event as any).properties?.part
             if (!part?.messageID) break

             // Fire turn-start on the first text part of a new user message
             const msg = messageStore.get(part.messageID)
-            if (msg?.role === "user" && part.type === "text" && !seenUserMessages.has(msg.id)) {
-              seenUserMessages.add(msg.id)
-              const sessionID = msg.sessionID ?? currentSessionID
-              if (sessionID) {
-                await callHook("turn-start", {
-                  session_id: sessionID,
-                  prompt: part.text ?? "",
-                  model: currentModel ?? "",
-                })
-              }
+            if (msg?.role === "user" && part.type === "text") {
+              await maybeStartTurn(msg.sessionID ?? currentSessionID, msg.id, part.text ?? "")
             }
             break
           }

           case "session.status": {
             // session.status fires in both TUI and non-interactive (run) mode.
             // session.idle is deprecated and not reliably emitted in run mode.
             const props = (event as any).properties
             if (props?.status?.type !== "idle") break
             const sessionID = props?.sessionID ?? currentSessionID
             if (!sessionID) break
+            // Ignore duplicate/late idle events when no corresponding turn-start ran.
+            if (!sessionsWithOpenTurn.has(sessionID)) break
+            sessionsWithOpenTurn.delete(sessionID)
             // Use sync variant: `opencode run` exits on the same idle event,
             // so an async hook would be killed before completing.
             callHookSync("turn-end", {
               session_id: sessionID,
               model: currentModel ?? "",
             })
             break
           }

           case "session.compacted": {
             const sessionID = (event as any).properties?.sessionID
             if (!sessionID) break
             await callHook("compaction", {
               session_id: sessionID,
             })
             break
           }

           case "session.deleted": {
             const session = (event as any).properties?.info
             if (!session?.id) break
             seenUserMessages.clear()
             messageStore.clear()
+            sessionsWithOpenTurn.delete(session.id)
             currentSessionID = null
             // Use sync variant: session-end may fire during shutdown.
             callHookSync("session-end", {
               session_id: session.id,
             })
             break
           }

           case "server.instance.disposed": {
             // Fires when OpenCode shuts down (TUI close or `opencode run` exit).
             // session.deleted only fires on explicit user deletion, not on quit,
             // so this is the only reliable way to end sessions on exit.
             if (!currentSessionID) break
             const sessionID = currentSessionID
             seenUserMessages.clear()
             messageStore.clear()
+            sessionsWithOpenTurn.delete(sessionID)
             currentSessionID = null
             // Use sync variant: this is the last event before process exit.
             callHookSync("session-end", {
               session_id: sessionID,
             })
             break
           }
         }
       } catch {
         // Silently ignore — plugin failures must not crash OpenCode
       }
     },
   }
 }

Index: cmd/entire/cli/agent/opencode/hooks_test.go
===================================================================
--- cmd/entire/cli/agent/opencode/hooks_test.go	
+++ cmd/entire/cli/agent/opencode/hooks_test.go	
@@ -1,264 +1,294 @@
 package opencode

 import (
 	"context"
 	"os"
 	"path/filepath"
 	"strings"
 	"testing"

 	"github.com/entireio/cli/cmd/entire/cli/agent"
 )

 // Compile-time check
 var _ agent.HookSupport = (*OpenCodeAgent)(nil)

 // Note: Hook tests cannot use t.Parallel() because t.Chdir() modifies process state.

 func TestInstallHooks_FreshInstall(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	count, err := ag.InstallHooks(context.Background(), false, false)
 	if err != nil {
 		t.Fatalf("unexpected error: %v", err)
 	}
 	if count != 1 {
 		t.Errorf("expected 1 hook installed, got %d", count)
 	}

 	// Verify plugin file was created
 	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
 	data, err := os.ReadFile(pluginPath)
 	if err != nil {
 		t.Fatalf("plugin file not created: %v", err)
 	}

 	content := string(data)
 	// The plugin uses JS template literal ${ENTIRE_CMD} — check the constant was set correctly
 	if !strings.Contains(content, `const ENTIRE_CMD = 'entire'`) {
 		t.Error("plugin file does not contain production command constant")
 	}
 	if !strings.Contains(content, "hooks opencode") {
 		t.Error("plugin file does not contain 'hooks opencode'")
 	}
 	if !strings.Contains(content, "EntirePlugin") {
 		t.Error("plugin file does not contain 'EntirePlugin' export")
 	}
 	// Should use production command
 	if strings.Contains(content, "go run") {
 		t.Error("plugin file contains 'go run' in production mode")
 	}
 }

 func TestInstallHooks_Idempotent(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	// First install
 	count1, err := ag.InstallHooks(context.Background(), false, false)
 	if err != nil {
 		t.Fatalf("first install failed: %v", err)
 	}
 	if count1 != 1 {
 		t.Errorf("first install: expected 1, got %d", count1)
 	}

 	// Second install — should be idempotent
 	count2, err := ag.InstallHooks(context.Background(), false, false)
 	if err != nil {
 		t.Fatalf("second install failed: %v", err)
 	}
 	if count2 != 0 {
 		t.Errorf("second install: expected 0 (idempotent), got %d", count2)
 	}
 }

 func TestInstallHooks_LocalDev(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	count, err := ag.InstallHooks(context.Background(), true, false)
 	if err != nil {
 		t.Fatalf("unexpected error: %v", err)
 	}
 	if count != 1 {
 		t.Errorf("expected 1 hook installed, got %d", count)
 	}

 	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
 	data, err := os.ReadFile(pluginPath)
 	if err != nil {
 		t.Fatalf("plugin file not created: %v", err)
 	}

 	content := string(data)
 	if !strings.Contains(content, `go run "$(git rev-parse --show-toplevel)"/cmd/entire/main.go`) {
 		t.Error("local dev mode: plugin file should use git rev-parse for go run path")
 	}
 }

 func TestInstallHooks_SessionStartIsGuardedBySessionSwitch(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	if _, err := ag.InstallHooks(context.Background(), false, false); err != nil {
 		t.Fatalf("install failed: %v", err)
 	}

 	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
 	data, err := os.ReadFile(pluginPath)
 	if err != nil {
 		t.Fatalf("plugin file not created: %v", err)
 	}

 	content := string(data)
 	guard := "if (currentSessionID !== session.id) {"
 	hook := `const proc = Bun.spawn(hookCmd("session-start"), {`
 	currentSessionAssignment := "currentSessionID = session.id"

 	guardIdx := strings.Index(content, guard)
 	hookIdx := strings.Index(content, hook)
 	assignIdx := strings.Index(content, currentSessionAssignment)

 	if guardIdx == -1 {
 		t.Fatalf("plugin file missing guard %q", guard)
 	}
 	if hookIdx == -1 {
 		t.Fatalf("plugin file missing session-start hook spawn %q", hook)
 	}
 	if assignIdx == -1 {
 		t.Fatalf("plugin file missing current session assignment %q", currentSessionAssignment)
 	}
 	if guardIdx >= hookIdx || hookIdx >= assignIdx {
 		t.Fatalf("expected guarded session-start call before session assignment, got guard=%d hook=%d assignment=%d",
 			guardIdx, hookIdx, assignIdx)
 	}
 	if !strings.Contains(content, `if ! command -v entire >/dev/null 2>&1; then exit 0; fi; exec entire hooks opencode ${hookName}`) {
 		t.Fatal("plugin file missing silent production hook command")
 	}
 }

 func TestInstallHooks_ForceReinstall(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	// First install
 	if _, err := ag.InstallHooks(context.Background(), false, false); err != nil {
 		t.Fatalf("first install failed: %v", err)
 	}

 	// Force reinstall
 	count, err := ag.InstallHooks(context.Background(), false, true)
 	if err != nil {
 		t.Fatalf("force install failed: %v", err)
 	}
 	if count != 1 {
 		t.Errorf("force install: expected 1, got %d", count)
 	}
 }

 func TestInstallHooks_RewritesWhenContentDiffers(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	// Install with localDev=true
 	count, err := ag.InstallHooks(context.Background(), true, false)
 	if err != nil {
 		t.Fatalf("first install failed: %v", err)
 	}
 	if count != 1 {
 		t.Errorf("first install: expected 1, got %d", count)
 	}

 	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
 	before, err := os.ReadFile(pluginPath)
 	if err != nil {
 		t.Fatalf("failed to read plugin file: %v", err)
 	}
 	if !strings.Contains(string(before), "go run") {
 		t.Fatal("expected localDev content with 'go run'")
 	}

 	// Reinstall with localDev=false (content differs) — should rewrite
 	count, err = ag.InstallHooks(context.Background(), false, false)
 	if err != nil {
 		t.Fatalf("second install failed: %v", err)
 	}
 	if count != 1 {
 		t.Errorf("second install with different content: expected 1, got %d", count)
 	}

 	after, err := os.ReadFile(pluginPath)
 	if err != nil {
 		t.Fatalf("failed to read plugin file after rewrite: %v", err)
 	}
 	if strings.Contains(string(after), "go run") {
 		t.Error("expected production content after rewrite, but still contains 'go run'")
 	}
 	if !strings.Contains(string(after), `const ENTIRE_CMD = 'entire'`) {
 		t.Error("expected production command constant after rewrite")
 	}
 }

+func TestInstallHooks_TurnLifecycleGuardsArePresent(t *testing.T) {
+	dir := t.TempDir()
+	t.Chdir(dir)
+	ag := &OpenCodeAgent{}
+
+	if _, err := ag.InstallHooks(context.Background(), false, false); err != nil {
+		t.Fatalf("install failed: %v", err)
+	}
+
+	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
+	data, err := os.ReadFile(pluginPath)
+	if err != nil {
+		t.Fatalf("plugin file not created: %v", err)
+	}
+
+	content := string(data)
+	if !strings.Contains(content, "const sessionsWithOpenTurn = new Set<string>()") {
+		t.Fatal("plugin file missing open-turn tracking set")
+	}
+	if !strings.Contains(content, "await maybeStartTurn(msg.sessionID ?? currentSessionID, msg.id, prompt)") {
+		t.Fatal("plugin file missing message.updated fallback turn-start")
+	}
+	if !strings.Contains(content, "if (!sessionsWithOpenTurn.has(sessionID)) break") {
+		t.Fatal("plugin file missing turn-end dedupe guard")
+	}
+	if !strings.Contains(content, "sessionsWithOpenTurn.delete(sessionID)") {
+		t.Fatal("plugin file missing turn-end session cleanup")
+	}
+}
+
 func TestUninstallHooks(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	if _, err := ag.InstallHooks(context.Background(), false, false); err != nil {
 		t.Fatalf("install failed: %v", err)
 	}

 	if err := ag.UninstallHooks(context.Background()); err != nil {
 		t.Fatalf("uninstall failed: %v", err)
 	}

 	pluginPath := filepath.Join(dir, ".opencode", "plugins", "entire.ts")
 	if _, err := os.Stat(pluginPath); !os.IsNotExist(err) {
 		t.Error("plugin file still exists after uninstall")
 	}
 }

 func TestUninstallHooks_NoFile(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	// Should not error when no plugin file exists
 	if err := ag.UninstallHooks(context.Background()); err != nil {
 		t.Fatalf("uninstall with no file should not error: %v", err)
 	}
 }

 func TestAreHooksInstalled(t *testing.T) {
 	dir := t.TempDir()
 	t.Chdir(dir)
 	ag := &OpenCodeAgent{}

 	if ag.AreHooksInstalled(context.Background()) {
 		t.Error("hooks should not be installed initially")
 	}

 	if _, err := ag.InstallHooks(context.Background(), false, false); err != nil {
 		t.Fatalf("install failed: %v", err)
 	}

 	if !ag.AreHooksInstalled(context.Background()) {
 		t.Error("hooks should be installed after InstallHooks")
 	}

 	if err := ag.UninstallHooks(context.Background()); err != nil {
 		t.Fatalf("uninstall failed: %v", err)
 	}

 	if ag.AreHooksInstalled(context.Background()) {
 		t.Error("hooks should not be installed after UninstallHooks")
 	}
 }

