 					"remote_hash", remoteRef.Hash().String()[:7],
 				)
 			}
 		}
 		return nil
 	}
 	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
 		return fmt.Errorf("failed to check metadata branch: %w", err)
