// deletes untracked directories (like .entire/) even when they're in .gitignore.
// Returns the short commit ID (7 chars) on success for display purposes.
func HardResetWithProtection(ctx context.Context, commitHash plumbing.Hash) (shortID string, err error) {
	hashStr := commitHash.String()
	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr)
	if output, err := cmd.CombinedOutput(); err != nil {
		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
	}

	// Return short commit ID for display
	shortID = hashStr
	if len(shortID) > 7 {
		shortID = shortID[:7]
	}
	return shortID, nil
}

// collectUntrackedFiles collects untracked files in the working directory that are
// NOT ignored by .gitignore. This is used to capture the initial state when starting
// a session, ensuring untracked files present at session start are preserved during rewind.

// redactSessionTranscript redacts the transcript once for use by both the compact
// package and the checkpoint stores. Returns the redacted bytes and the duration
// of the redaction operation for perf logging.
func redactSessionTranscript(ctx context.Context, transcript []byte) (redact.RedactedBytes, time.Duration, error) {
	start := time.Now()
	_, span := perf.Start(ctx, "redact_transcript")
	defer span.End()

	if len(transcript) == 0 {
		return redact.RedactedBytes{}, time.Since(start), nil
	}

	redacted, err := redactSessionJSONLBytes(transcript)
	if err != nil {
		span.RecordError(err)
		return redact.RedactedBytes{}, time.Since(start), fmt.Errorf("failed to redact transcript secrets: %w", err)
	}
	return redacted, time.Since(start), nil
}

